{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Sorafenib absolute oral bioavailability is 38–49% in patients with metastatic renal cell carcinoma, a direct human F measurement well above the 20% threshold; high transferability supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Safinamide absolute oral bioavailability is 95% in healthy subjects after a 50 mg IR tablet versus IV, indicating essentially complete absorption; high transferability supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "The active metabolite of nabumetone has an absolute bioavailability of 38% in healthy young subjects, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Meperidine absolute oral bioavailability is 47–73% in healthy men, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Atenolol absolute bioavailability is 0.56 ± 0.17 in normal subjects, showing that even a polar beta-blocker exceeds the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Betaxolol absolute bioavailability is 0.84 ± 0.07 in healthy male subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Posaconazole suspension absolute bioavailability was 16% (8–27%) in immunocompromised pediatric patients, a contradictory low-F data point, but it is formulation/population-specific and outweighed by the high-F analogue consensus.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer human absolute bioavailability evidence overwhelmingly indicates F ≥20%: sorafenib 38–49%, safinamide 95%, nabumetone metabolite 38%, meperidine 47–73%, atenolol ~50–60%, betaxolol ~84%, and ciprofibrate ~90%. The only low value (posaconazole 16% in pediatric patients on suspension) is context-specific and does not outweigh the consensus. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental F for the query molecule.",
    "No data on the query's solubility, permeability, first-pass metabolism, or transporter effects.",
    "The query's polyhydroxylated bicyclic acetal is not represented by an exact analogue.",
    "One sorafenib record reports ~8.5% but conflicts with multiple absolute bioavailability studies."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

